INSERT INTO "compatibility_matrix" VALUES(1,'rtx-5090-32gb-run-deepseek-r1-distill-qwen-1-5b',1,1,1.09,1.3,1.9,3.56,0.22,0.88,2.16,'OPTIMAL_Q8','Runs Smoothly at Q8_0 (Near-Lossless)',695.8,'Q8_0 (8-bit)','All 28/28 layers (100% GPU)','ollama run deepseek-r1:1.5b','llama-cli -hf deepseek-ai/DeepSeek-R1-Distill-Qwen-1.5B-GGUF:Q4_K_M -ngl 99 -c 8192 -fa','LOCAL_HARDWARE_CTA','Yes — the NVIDIA RTX 5090 32GB (32 GB VRAM) easily runs DeepSeek R1 Distill Qwen 1.5B at Q8_0 precision (3.0 GB total with 8K context), delivering ~695.8 tokens/sec with zero CPU offload.','published','2026-11-27 04:07:40','2026-11-27 04:07:40');
INSERT INTO "compatibility_matrix" VALUES(2,'rtx-5090-32gb-run-deepseek-r1-distill-qwen-7b',1,2,4.65,5.56,8.15,15.24,0.44,1.75,5.94,'OPTIMAL_Q8','Runs Smoothly at Q8_0 (Near-Lossless)',162.6,'Q8_0 (8-bit)','All 28/28 layers (100% GPU)','ollama run deepseek-r1:7b','llama-cli -hf deepseek-ai/DeepSeek-R1-Distill-Qwen-7B-GGUF:Q4_K_M -ngl 99 -c 8192 -fa','LOCAL_HARDWARE_CTA','Yes — the NVIDIA RTX 5090 32GB (32 GB VRAM) easily runs DeepSeek R1 Distill Qwen 7B at Q8_0 precision (9.4 GB total with 8K context), delivering ~162.6 tokens/sec with zero CPU offload.','published','2026-11-27 04:07:40','2026-11-27 04:07:40');
