INSERT INTO "compatibility_matrix" VALUES(955,'apple-m1-16gb-run-phi-4-14b',32,25,8.94,10.7,15.69,29.32,1.56,6.25,11.35,'OPTIMAL_Q4','Runs Smoothly at Q4_K_M (Full GPU)',5.2,'Q4_K_M (4-bit)','All 40/40 layers (100% GPU)','ollama run phi4:14b','llama-cli -hf microsoft/phi-4-GGUF:Q4_K_M -ngl 99 -c 8192 -fa','LOCAL_HARDWARE_CTA','Yes — the Apple M1 16GB (12 GB VRAM) fits Microsoft Phi-4 14B Q4_K_M completely in VRAM (11.3 GB needed at 8K context), achieving ~5.2 tokens/sec.','enriched',NULL,'2026-11-27 04:03:02');
