INSERT INTO "compatibility_matrix" VALUES(957,'apple-m1-16gb-run-mistral-7b-v0-3',32,27,4.42,5.29,7.76,14.5,1.0,4.0,6.27,'OPTIMAL_Q8','Runs Smoothly at Q8_0 (Near-Lossless)',6.5,'Q8_0 (8-bit)','All 32/32 layers (100% GPU)','ollama run mistral:7b','llama-cli -hf mistralai/Mistral-7B-Instruct-v0.3-GGUF:Q4_K_M -ngl 99 -c 8192 -fa','LOCAL_HARDWARE_CTA','Yes — the Apple M1 16GB (12 GB VRAM) easily runs Mistral 7B v0.3 at Q8_0 precision (9.6 GB total with 8K context), delivering ~6.5 tokens/sec with zero CPU offload.','enriched',NULL,'2026-11-27 04:03:02');
