INSERT INTO "compatibility_matrix" VALUES(960,'apple-m1-16gb-run-mixtral-8x7b-moe',32,30,28.49,34.09,49.97,93.4,1.0,4.0,30.34,'OOM_CLOUD','Out of Memory (Cloud GPU Recommended)',0.0,'Cloud GPU Required','0 layers (Exceeds VRAM capacity)','ollama run mixtral:8x7b','llama-cli -hf mistralai/Mixtral-8x7B-Instruct-v0.1-GGUF:Q4_K_M -ngl 0 -c 8192 -fa','CLOUD_GPU_CTA','No — Mixtral 8x7B (MoE) requires 30.3 GB VRAM at Q4_K_M, which causes an Out-of-Memory (OOM) error on the Apple M1 16GB (12 GB). Renting a cloud RTX 3090 24GB is recommended.','enriched',NULL,'2026-11-27 04:03:02');
